insert into rwadar_catalogo.plataformas (revision_id,plataforma_id,fecha_canonica_conservada,estado_operativo,estado_operativo_detalle,licencia_registro,licencia_registro_detalle,acceso,acceso_detalle) select 'a0df3111-37c9-a767-f4d8-93c56095150b'::uuid,id,'2026-07-26'::date,'observada'::rwadar_catalogo.estado_operativo,'La página oficial Web3 mantiene productos de tesorería, suscripción y reembolso; no se realizó onboarding.','confirmada_regulador'::rwadar_catalogo.estado_licencia,'La AMF (GECO) registra SPIKO EU T-BILLS MONEY MARKET FUND (ISIN FR001400ODL1), compartimento de SPIKO SICAV: OPCVM vivo, autorizado (agrément) el 05/04/2024 y abierto a todo suscriptor. Su gestora es Twenty First Capital, no Spiko, y el depositario es CACEIS Bank. El registro REGAFI de la ACPR recoge a Spiko Finance como empresa de inversión autorizada (CIB 19183) desde el 15/12/2025. Solo se verificó ese compartimento; los demás fondos Spiko deben comprobarse uno a uno.','confirmado_condicionado'::rwadar_catalogo.estado_acceso,'Spiko declara que sus fondos UCITS pueden aceptar inversores no profesionales, y la AMF marca el compartimento EU T-Bills como abierto a todo suscriptor. El registro REGAFI de la ACPR muestra que Spiko Finance tiene pasaporte de libre prestación de servicios en España desde el 08/01/2026 para recibir y transmitir órdenes sobre participaciones de IIC. No se comprobó en la CNMV la comercialización del fondo en España ni se hizo el onboarding.' from public.plataformas where slug='spiko' on conflict (revision_id,plataforma_id) do nothing;
